H.background();
// Atwood machine:  a = (m2 − m1) g / (m1 + m2),   T = 2 m1 m2 g / (m1 + m2).
// Two masses hang over a pulley. The heavier side accelerates down, the lighter
// up, at the SAME magnitude a (one string). Masses bob up/down on a loop.
const g = 9.8;
const m1 = Math.max(0.1, P.m1);   // left mass
const m2 = Math.max(0.1, P.m2);   // right mass
const a = (m2 - m1) * g / (m1 + m2);          // + means m2 (right) accelerates down
const T = 2 * m1 * m2 * g / (m1 + m2);
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: 0, yMax: 8, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
// ceiling + pulley
v.line(-3, 7.5, 3, 7.5, { color: H.colors.axis, width: 4 });
const pcx = 0, pcy = 6.6, pr = 0.6;
const pts = [];
for (let i = 0; i <= 40; i++) { const aa = i / 40 * H.TAU; pts.push([pcx + pr * Math.cos(aa), pcy + pr * Math.sin(aa)]); }
v.path(pts, { color: H.colors.accent2, width: 3, close: true });
v.line(0, 7.5, 0, 7.2, { color: H.colors.axis, width: 2 });
// equilibrium heights of each hanging mass
const yL0 = 3.5, yR0 = 3.5;
// bob: the heavier side moves DOWN. Use a bounded triangle-wave so it loops.
const dir = a >= 0 ? 1 : -1;                  // right goes down if a>0
const swing = 1.3 * Math.sin(t * 0.9);        // displacement, bounded
const yR = yR0 - dir * swing;                 // right mass
const yL = yL0 + dir * swing;                 // left mass (opposite)
const xL = -pr, xR = pr;
// strings over the pulley
v.line(xL, pcy, xL, yL + 0.5, { color: H.colors.sub, width: 2 });
v.line(xR, pcy, xR, yR + 0.5, { color: H.colors.sub, width: 2 });
// mass boxes sized by mass
const sz1 = 0.5 + 0.5 * Math.min(m1, 8) / 8, sz2 = 0.5 + 0.5 * Math.min(m2, 8) / 8;
v.rect(xL - sz1, yL - sz1, 2 * sz1, 2 * sz1, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
v.rect(xR - sz2, yR - sz2, 2 * sz2, 2 * sz2, { fill: H.colors.panel, stroke: H.colors.warn, width: 2 });
v.text("m1", xL, yL, { color: H.colors.ink, size: 12, align: "center" });
v.text("m2", xR, yR, { color: H.colors.ink, size: 12, align: "center" });
// tension arrows up on each mass, weights down
const SF = 1.4 / Math.max(T, m1 * g, m2 * g, 1e-6);
v.arrow(xL, yL + sz1, xL, yL + sz1 + T * SF, { color: H.colors.good, width: 2.5 });
v.arrow(xR, yR + sz2, xR, yR + sz2 + T * SF, { color: H.colors.good, width: 2.5 });
v.arrow(xL, yL - sz1, xL, yL - sz1 - m1 * g * SF, { color: H.colors.violet, width: 2.5 });
v.arrow(xR, yR - sz2, xR, yR - sz2 - m2 * g * SF, { color: H.colors.violet, width: 2.5 });
